export type LvrtPowerPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function lvrtPowerProgram() {
  return <T extends LvrtPowerPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { lvrtPower: LvrtPowerPlugin }> => {
    return extendClient(client, {
      lvrtPower: {
        accounts: {
          powerConfig: addSelfFetchFunctions(client, getPowerConfigCodec()),
          powerMarket: addSelfFetchFunctions(client, getPowerMarketCodec()),
          shortVault: addSelfFetchFunctions(client, getShortVaultCodec()),
        },
        instructions: {
          accrueFunding: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAccrueFundingInstruction(input),
            ),
          ammBuy: (input) =>
            addSelfPlanAndSendFunctions(client, getAmmBuyInstruction(input)),
          ammSell: (input) =>
            addSelfPlanAndSendFunctions(client, getAmmSellInstruction(input)),
          applySplit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getApplySplitInstructionAsync(input),
            ),
          burnShort: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBurnShortInstructionAsync(input),
            ),
          crabDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCrabDepositInstruction(input),
            ),
          createPowerMarket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreatePowerMarketInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          initialize: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          liquidateShort: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLiquidateShortInstruction(input),
            ),
          mintShort: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getMintShortInstructionAsync(input),
            ),
          redeemAtIndex: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRedeemAtIndexInstruction(input),
            ),
          seedAmm: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSeedAmmInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          shortVault: findShortVaultPda,
          market: findMarketPda,
          powerMint: findPowerMintPda,
          usdcVault: findUsdcVaultPda,
          tokenVault: findTokenVaultPda,
        },
        identifyAccount: identifyLvrtPowerAccount,
        identifyInstruction: identifyLvrtPowerInstruction,
        parseInstruction: parseLvrtPowerInstruction,
      } as LvrtPowerPlugin,
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
